import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"解","description":"焦氏易林注 - 解","frontmatter":{"title":"解","description":"焦氏易林注 - 解"},"headers":[],"relativePath":"zh/classics/jiaoyilin/040.md","filePath":"zh/classics/jiaoyilin/040.md"}'),l={name:"zh/classics/jiaoyilin/040.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="解" tabindex="-1">解 <a class="header-anchor" href="#解" aria-label="Permalink to “解”">​</a></h1><h3 id="解-1" tabindex="-1">解 <a class="header-anchor" href="#解-1" aria-label="Permalink to “解”">​</a></h3><h3 id="解之乾" tabindex="-1">解之乾 <a class="header-anchor" href="#解之乾" aria-label="Permalink to “解之乾”">​</a></h3><h3 id="林辞" tabindex="-1">林辞 <a class="header-anchor" href="#林辞" aria-label="Permalink to “林辞”">​</a></h3><p>大都之居，無物不具。抱布貿絲，所求必得。</p><h3 id="注" tabindex="-1">注 <a class="header-anchor" href="#注" aria-label="Permalink to “注”">​</a></h3><p>伏坤為大都、為萬物、為布。抱布貿絲，《衛風》語。</p><h3 id="解之坤" tabindex="-1">解之坤 <a class="header-anchor" href="#解之坤" aria-label="Permalink to “解之坤”">​</a></h3><h3 id="林辞-1" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-1" aria-label="Permalink to “林辞”">​</a></h3><p>膠著木連，不出牢關，家室相安。</p><h3 id="注-1" tabindex="-1">注 <a class="header-anchor" href="#注-1" aria-label="Permalink to “注”">​</a></h3><p>此用《解》象。坎為膠、為木，與震木連體，故曰木連。坎為牢、為室，重坎故不出。</p><h3 id="解之屯" tabindex="-1">解之屯 <a class="header-anchor" href="#解之屯" aria-label="Permalink to “解之屯”">​</a></h3><h3 id="林辞-2" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-2" aria-label="Permalink to “林辞”">​</a></h3><p>孟伯食長，懼其畏王。賴四蒙五，抱福歸房。</p><h3 id="注-2" tabindex="-1">注 <a class="header-anchor" href="#注-2" aria-label="Permalink to “注”">​</a></h3><p>震為孟伯、為長、為口，故曰食長。坎為畏懼，震為王，卦數四，坎納戊，數五，故曰賴四蒙五。艮為抱、為房，震為福，故曰抱福歸房。</p><h3 id="解之蒙" tabindex="-1">解之蒙 <a class="header-anchor" href="#解之蒙" aria-label="Permalink to “解之蒙”">​</a></h3><h3 id="林辞-3" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-3" aria-label="Permalink to “林辞”">​</a></h3><p>朽輿疲駟，不任銜佩。君子服之，談何容易。</p><h3 id="注-3" tabindex="-1">注 <a class="header-anchor" href="#注-3" aria-label="Permalink to “注”">​</a></h3><p>震為車、為馬，坤敝故曰朽、曰疲。震口為銜，艮手為佩。艮為君子，坤為服。服，用也，言車馬不良不易駕馭。</p><h3 id="解之需" tabindex="-1">解之需 <a class="header-anchor" href="#解之需" aria-label="Permalink to “解之需”">​</a></h3><h3 id="林辞-4" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-4" aria-label="Permalink to “林辞”">​</a></h3><p>許嫁既婚，利福在身。適惠生桓，為我魯君。</p><h3 id="注-4" tabindex="-1">注 <a class="header-anchor" href="#注-4" aria-label="Permalink to “注”">​</a></h3><p>《左傳隱元年》：&quot;宋武公生惠子，惠子生而有文在其手，曰為魯夫人，故歸&quot;，惠公生桓公，因手文故曰利福在身。坎為婚，伏坤為身，兌為魯，乾為君。</p><h3 id="解之訟" tabindex="-1">解之訟 <a class="header-anchor" href="#解之訟" aria-label="Permalink to “解之訟”">​</a></h3><h3 id="林辞-5" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-5" aria-label="Permalink to “林辞”">​</a></h3><p>入門大喜，上堂見母。妻子俱在，兄弟饒有。</p><h3 id="注-5" tabindex="-1">注 <a class="header-anchor" href="#注-5" aria-label="Permalink to “注”">​</a></h3><p>巽為入，乾為門，伏震為喜，故入門大喜。坎為室，故為堂。巽為母，伏震故上堂見母。離為坎妻，震為子、為兄，坎為弟。○有，宋元本作友，依汲古。</p><h3 id="解之師" tabindex="-1">解之師 <a class="header-anchor" href="#解之師" aria-label="Permalink to “解之師”">​</a></h3><h3 id="林辞-6" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-6" aria-label="Permalink to “林辞”">​</a></h3><p>推車上山，力不能任。顛蹶蹉跌，傷我中心。</p><h3 id="注-6" tabindex="-1">注 <a class="header-anchor" href="#注-6" aria-label="Permalink to “注”">​</a></h3><p>坤為車，震往，故曰推車。震為陵，故曰上山，坤弱故不能任，坎蹇故顛蹶蹉跌。坎為心、為中，坎破故傷。</p><h3 id="解之比" tabindex="-1">解之比 <a class="header-anchor" href="#解之比" aria-label="Permalink to “解之比”">​</a></h3><h3 id="林辞-7" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-7" aria-label="Permalink to “林辞”">​</a></h3><p>鷹飛退去，不食其雛。禽尚如此，何況人乎。</p><h3 id="注-7" tabindex="-1">注 <a class="header-anchor" href="#注-7" aria-label="Permalink to “注”">​</a></h3><p>艮為鷹、為飛，坎隱伏故退去。兌為食、為雛，兌伏，故不食其雛。○乎，宋元本作與，依汲古。</p><h3 id="解之小畜" tabindex="-1">解之小畜 <a class="header-anchor" href="#解之小畜" aria-label="Permalink to “解之小畜”">​</a></h3><h3 id="林辞-8" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-8" aria-label="Permalink to “林辞”">​</a></h3><p>福棄我走，利不可得。幽人利貞，終無怨慝。</p><h3 id="注-8" tabindex="-1">注 <a class="header-anchor" href="#注-8" aria-label="Permalink to “注”">​</a></h3><p>乾福，風隕，故福棄我走。巽為利，在外，故利不可得。艮為幽人、為終，坎怨慝，正伏象雜用。</p><h3 id="解之履" tabindex="-1">解之履 <a class="header-anchor" href="#解之履" aria-label="Permalink to “解之履”">​</a></h3><h3 id="林辞-9" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-9" aria-label="Permalink to “林辞”">​</a></h3><p>夫妻反目，不能正室。翁雲於南，嫗言還北。並後匹嫡，二政亂國。</p><h3 id="注-9" tabindex="-1">注 <a class="header-anchor" href="#注-9" aria-label="Permalink to “注”">​</a></h3><p>伏坎為夫，離為妻、為目，離上下兩半目相對，坎上下兩半目相背，故曰反目。坎為室、為邪曲，故曰不能正室。乾為父，位南故曰翁雲於南。伏坤為母、為北，故曰嫗言還北。坤為後、為政、為國、為亂，數二，故曰並後、曰匹敵、曰二政。震為嫡也。○翁，汲古作公，嫗作姬，依宋元本。林意謂政權不一，國必亂也。</p><h3 id="解之泰" tabindex="-1">解之泰 <a class="header-anchor" href="#解之泰" aria-label="Permalink to “解之泰”">​</a></h3><h3 id="林辞-10" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-10" aria-label="Permalink to “林辞”">​</a></h3><p>陽衰伏匿，陰淫為賊。賴幸王孫，遂至嘉國。</p><h3 id="注-10" tabindex="-1">注 <a class="header-anchor" href="#注-10" aria-label="Permalink to “注”">​</a></h3><p>陽在下故曰伏匿，陰在上故曰陰淫。坤殺兌折，故曰賊。震為王、為嘉，坤為國。○賴幸，汲古作幸賴，依宋元本。嘉，汲古作家，依宋本。</p><h3 id="解之否" tabindex="-1">解之否 <a class="header-anchor" href="#解之否" aria-label="Permalink to “解之否”">​</a></h3><h3 id="林辞-11" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-11" aria-label="Permalink to “林辞”">​</a></h3><p>入山求王，不見和璞。終日至暮，勞無所得。</p><h3 id="注-11" tabindex="-1">注 <a class="header-anchor" href="#注-11" aria-label="Permalink to “注”">​</a></h3><p>巽為入，艮為山、為求，乾為玉、為璞，楚人卞和得璞玉，故曰和璞，巽伏故不見。艮為日、為終，坤為暮、為勞，坤虛故無得。○山，汲古作水，坤水亦可從。</p><h3 id="解之同人" tabindex="-1">解之同人 <a class="header-anchor" href="#解之同人" aria-label="Permalink to “解之同人”">​</a></h3><h3 id="林辞-12" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-12" aria-label="Permalink to “林辞”">​</a></h3><p>鳴鸞四牡，駕出行狩。合格有獲，獻公飲酒。</p><h3 id="注-12" tabindex="-1">注 <a class="header-anchor" href="#注-12" aria-label="Permalink to “注”">​</a></h3><p>通《師》。震為鳴鸞、為馬，卦數四，故曰四牡。震為行、為狩，坎為獲、為酒，震為公。</p><h3 id="解之大有" tabindex="-1">解之大有 <a class="header-anchor" href="#解之大有" aria-label="Permalink to “解之大有”">​</a></h3><h3 id="林辞-13" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-13" aria-label="Permalink to “林辞”">​</a></h3><p>覆手舉牘，易為功力。正月元日，平飲致福。</p><h3 id="注-13" tabindex="-1">注 <a class="header-anchor" href="#注-13" aria-label="Permalink to “注”">​</a></h3><p>通《比》。艮為手為舉。牘，木簡也，所以作書。坤為文，坎為木，故曰牘。坎為月、為中正，離為日，乾為元，故曰元日。坎為平、為飲。《史記魏其侯傳》：灌夫與長樂衛尉飲，輕重不得其平，茲曰平飲。則兩人對飲輕重得平也。○正月，元刊作月正，依汲古。平飲，汲古作永平，依宋元本。舉牘，汲古作齊犢，依宋元本。</p><h3 id="解之謙" tabindex="-1">解之謙 <a class="header-anchor" href="#解之謙" aria-label="Permalink to “解之謙”">​</a></h3><h3 id="林辞-14" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-14" aria-label="Permalink to “林辞”">​</a></h3><p>三火起明，雨滅其光。高位疾顛，驕恣誅傷。</p><h3 id="注-14" tabindex="-1">注 <a class="header-anchor" href="#注-14" aria-label="Permalink to “注”">​</a></h3><p>詳《大有》之《師》。</p><h3 id="解之豫" tabindex="-1">解之豫 <a class="header-anchor" href="#解之豫" aria-label="Permalink to “解之豫”">​</a></h3><h3 id="林辞-15" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-15" aria-label="Permalink to “林辞”">​</a></h3><p>裹糗荷糧，與利相逢。高飛有得，君子獲福。</p><h3 id="注-15" tabindex="-1">注 <a class="header-anchor" href="#注-15" aria-label="Permalink to “注”">​</a></h3><p>震為糗糧，艮為荷，伏巽為利，艮為高飛、為君子。○得，宋元作德，子作大，均依汲古。裹，汲古作裒，非，依宋元本。</p><h3 id="解之隨" tabindex="-1">解之隨 <a class="header-anchor" href="#解之隨" aria-label="Permalink to “解之隨”">​</a></h3><h3 id="林辞-16" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-16" aria-label="Permalink to “林辞”">​</a></h3><p>水土相得，萬物蕃殖。膏澤優沃，君子有德。</p><h3 id="注-16" tabindex="-1">注 <a class="header-anchor" href="#注-16" aria-label="Permalink to “注”">​</a></h3><p>兌為水，艮為土，震為萬物、為蕃鮮，故曰蕃殖。兌為膏澤、為優沃，艮為君子。○德，汲古作得，依宋元本。</p><h3 id="解之蠱" tabindex="-1">解之蠱 <a class="header-anchor" href="#解之蠱" aria-label="Permalink to “解之蠱”">​</a></h3><h3 id="林辞-17" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-17" aria-label="Permalink to “林辞”">​</a></h3><p>道理和得，人不相賊。君子往之，樂有利福。</p><h3 id="注-17" tabindex="-1">注 <a class="header-anchor" href="#注-17" aria-label="Permalink to “注”">​</a></h3><p>艮為道，震為人、為樂，巽為利。</p><h3 id="解之臨" tabindex="-1">解之臨 <a class="header-anchor" href="#解之臨" aria-label="Permalink to “解之臨”">​</a></h3><h3 id="林辞-18" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-18" aria-label="Permalink to “林辞”">​</a></h3><p>天孫帝子，與日月處。光榮於世，福祿繁祉。</p><h3 id="注-18" tabindex="-1">注 <a class="header-anchor" href="#注-18" aria-label="Permalink to “注”">​</a></h3><p>伏艮為天、為孫，震為帝、為子，故曰天孫帝子。伏乾為日，兌為月，《漢書天文志》：&quot;織女，天帝孫也&quot;，伏艮為星，故曰與日月處。</p><h3 id="解之觀" tabindex="-1">解之觀 <a class="header-anchor" href="#解之觀" aria-label="Permalink to “解之觀”">​</a></h3><h3 id="林辞-19" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-19" aria-label="Permalink to “林辞”">​</a></h3><p>陪依在位，乘非其器。折足覆餗，毀傷寶玉。</p><h3 id="注-19" tabindex="-1">注 <a class="header-anchor" href="#注-19" aria-label="Permalink to “注”">​</a></h3><p>坤順故曰陪依。艮為貴、為位，坤為車、為小人，以小人而乘車故曰非器。又震為器，震覆故非器。震為足、為餗、為玉，震覆，故折足覆餗，故傷玉。○陪依，汲古作部衣，依宋元本，然部衣或為布衣之訛。布衣在位，故乘非其器。</p><h3 id="解之噬嗑" tabindex="-1">解之噬嗑 <a class="header-anchor" href="#解之噬嗑" aria-label="Permalink to “解之噬嗑”">​</a></h3><h3 id="林辞-20" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-20" aria-label="Permalink to “林辞”">​</a></h3><p>鷁飛中退，舉事不遂。且守仁德，猶恐失墜。</p><h3 id="注-20" tabindex="-1">注 <a class="header-anchor" href="#注-20" aria-label="Permalink to “注”">​</a></h3><p>《左傳》：六鷁退飛，宋襄圖霸不成，故曰舉事不遂。艮為鷁、為飛，震為歸，故曰退。艮為守，震為仁，坎為失。○恐，宋元作免，依汲古。</p><h3 id="解之賁" tabindex="-1">解之賁 <a class="header-anchor" href="#解之賁" aria-label="Permalink to “解之賁”">​</a></h3><h3 id="林辞-21" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-21" aria-label="Permalink to “林辞”">​</a></h3><p>經棗正冠，意盈不廉。桀紂迷讒，惑佞傷賢，使國亂煩。</p><h3 id="注-21" tabindex="-1">注 <a class="header-anchor" href="#注-21" aria-label="Permalink to “注”">​</a></h3><p>艮為棗、為冠艮手為正，正冠舉手有類摘果，故曰不廉。盈，極也。離為惡人，故曰桀紂。坎為迷惑，三至上正反震，故曰讒佞。艮為賢、為國。離為亂。○棗，宋元本作棘，依汲古。正，汲古作整，廉作厭，均依宋元本。讒惑，宋、汲古本作惑讒，今依元本。</p><h3 id="解之剝" tabindex="-1">解之剝 <a class="header-anchor" href="#解之剝" aria-label="Permalink to “解之剝”">​</a></h3><h3 id="林辞-22" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-22" aria-label="Permalink to “林辞”">​</a></h3><p>申酉退跌，陰慝前作。柯條華枝，復泥不白。</p><h3 id="注-22" tabindex="-1">注 <a class="header-anchor" href="#注-22" aria-label="Permalink to “注”">​</a></h3><p>候卦申否酉觀戌剝陽退，故曰跌。陰日增，故曰作。艮為柯條，伏兌為華，震為白，震覆故不白。○慝，汲古作雨，非，依宋元本。華枝疑枝葉之訛。</p><h3 id="解之復" tabindex="-1">解之復 <a class="header-anchor" href="#解之復" aria-label="Permalink to “解之復”">​</a></h3><h3 id="林辞-23" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-23" aria-label="Permalink to “林辞”">​</a></h3><p>平正賤使，主服苦事。</p><h3 id="注-23" tabindex="-1">注 <a class="header-anchor" href="#注-23" aria-label="Permalink to “注”">​</a></h3><p>震為主，坤賤而役萬物，故主服苦事。</p><h3 id="解之無妄" tabindex="-1">解之無妄 <a class="header-anchor" href="#解之無妄" aria-label="Permalink to “解之無妄”">​</a></h3><h3 id="林辞-24" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-24" aria-label="Permalink to “林辞”">​</a></h3><p>釣魴河湄，水泛無涯。振衣徒歸，上下昏迷。屬公遜齊。</p><h3 id="注-24" tabindex="-1">注 <a class="header-anchor" href="#注-24" aria-label="Permalink to “注”">​</a></h3><p>巽為魚，艮手為釣，乾為河海，乾大故水無涯。乾為衣，震為歸、為公，互巽為齊，《左傳昭二十五年》公孫於齊註：&quot;諱奔，猶遜讓而去也，孫音遜。&quot;○泛，宋元本作長，衣作手，均依汲古。</p><h3 id="解之大畜" tabindex="-1">解之大畜 <a class="header-anchor" href="#解之大畜" aria-label="Permalink to “解之大畜”">​</a></h3><h3 id="林辞-25" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-25" aria-label="Permalink to “林辞”">​</a></h3><p>胎養蒙生，始見兆形。遭逢雷電，摧角折頸。採山頭，終安不傾。</p><h3 id="注-25" tabindex="-1">注 <a class="header-anchor" href="#注-25" aria-label="Permalink to “注”">​</a></h3><p>震為胎、為萌芽，艮為龜，故曰兆形。震為雷電，艮為角、為頸，兌毀故折角摧頸。震為草莽，故曰。《詩墉風》言採其蝱，註：蝱，貝母也。艮為山頭、為終、為安。</p><h3 id="解之頤" tabindex="-1">解之頤 <a class="header-anchor" href="#解之頤" aria-label="Permalink to “解之頤”">​</a></h3><h3 id="林辞-26" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-26" aria-label="Permalink to “林辞”">​</a></h3><p>陽春枯槁，夏多水潦。霜雹俱作，傷我禾黍，年歲困苦。</p><h3 id="注-26" tabindex="-1">注 <a class="header-anchor" href="#注-26" aria-label="Permalink to “注”">​</a></h3><p>震為春，坤死，故枯槁。坤為水，互重坤，故曰多水。卦本大離，故曰夏。坤為霜、為冰，故曰雹。震為禾稼，坤為年歲。○作，宋元本作擊，依汲古。</p><h3 id="解之大過" tabindex="-1">解之大過 <a class="header-anchor" href="#解之大過" aria-label="Permalink to “解之大過”">​</a></h3><h3 id="林辞-27" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-27" aria-label="Permalink to “林辞”">​</a></h3><p>三耳六齒，痛疾不已。齲病蠧缺，墮落其宅。</p><h3 id="注-27" tabindex="-1">注 <a class="header-anchor" href="#注-27" aria-label="Permalink to “注”">​</a></h3><p>兌為耳，艮數三，故曰三耳。兌為齒，乾數六，故曰六齒。伏坤為疾痛，正反兌故曰齲，齲，齒缺也。巽為蟲，故曰蠧，巽隕故墮落。○耳，宋元本作身，依汲古。</p><h3 id="解之坎" tabindex="-1">解之坎 <a class="header-anchor" href="#解之坎" aria-label="Permalink to “解之坎”">​</a></h3><h3 id="林辞-28" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-28" aria-label="Permalink to “林辞”">​</a></h3><p>失時無友，嘉耦出走，傫如喪狗。</p><h3 id="注-28" tabindex="-1">注 <a class="header-anchor" href="#注-28" aria-label="Permalink to “注”">​</a></h3><p>坎為失，艮為時、為友，震為嘉、為走，艮為狗、為家，二四艮覆，故如喪家之狗。《史記孔子世家》：&quot;儽儽然如喪家之狗&quot;。○時，宋元作恃，非，依汲古。傫儽同。</p><h3 id="解之離" tabindex="-1">解之離 <a class="header-anchor" href="#解之離" aria-label="Permalink to “解之離”">​</a></h3><h3 id="林辞-29" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-29" aria-label="Permalink to “林辞”">​</a></h3><p>宣重微民，歲樂年息。有國無咎，君子安喜。</p><h3 id="注-29" tabindex="-1">注 <a class="header-anchor" href="#注-29" aria-label="Permalink to “注”">​</a></h3><p>重離故曰宣重，宣，明也，言宣重光於民也。微字恐有訛。伏震為年歲、為樂、為息，伏艮為國、為君子。</p><h3 id="解之咸" tabindex="-1">解之咸 <a class="header-anchor" href="#解之咸" aria-label="Permalink to “解之咸”">​</a></h3><h3 id="林辞-30" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-30" aria-label="Permalink to “林辞”">​</a></h3><p>登幾上車，駕駟南游。合從散橫，燕秦以強。</p><h3 id="注-30" tabindex="-1">注 <a class="header-anchor" href="#注-30" aria-label="Permalink to “注”">​</a></h3><p>詳《屯》之《否》。</p><h3 id="解之恒" tabindex="-1">解之恒 <a class="header-anchor" href="#解之恒" aria-label="Permalink to “解之恒”">​</a></h3><h3 id="林辞-31" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-31" aria-label="Permalink to “林辞”">​</a></h3><p>鳥集茂林，柔順利貞。心樂願得，感戴慈母。</p><h3 id="注-31" tabindex="-1">注 <a class="header-anchor" href="#注-31" aria-label="Permalink to “注”">​</a></h3><p>通《益》。艮為鳥，正反艮故曰鳥集。震為林，正反震故曰茂林。坤為柔順，巽為利，艮為貞，坤為心、為慈母，艮為戴。○林，宋本、汲古本作木，依元本。易林讀林略如凌，以與貞韻，其例甚多，今晉音仍如此，汲古願得下多&quot;鳥鵲食榖，張口受哺&quot;二句，今依宋元本。</p><h3 id="解之遯" tabindex="-1">解之遯 <a class="header-anchor" href="#解之遯" aria-label="Permalink to “解之遯”">​</a></h3><h3 id="林辞-32" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-32" aria-label="Permalink to “林辞”">​</a></h3><p>啟蟄始生，萬物美榮。祉祿未成，市賈無贏。</p><h3 id="注-32" tabindex="-1">注 <a class="header-anchor" href="#注-32" aria-label="Permalink to “注”">​</a></h3><p>通《臨》。震為春、為生，故曰啟蟄始生。震為蕃鮮，故曰萬物美榮。乾為祉祿，陽消故未成。巽為市賈，巽隕故無贏。○祉祿未成，局本作福祿來成，來為未之訛字，依宋元本。贏，元本作盈，義同。賈，汲古訛買，依宋元本。</p><h3 id="解之大壯" tabindex="-1">解之大壯 <a class="header-anchor" href="#解之大壯" aria-label="Permalink to “解之大壯”">​</a></h3><h3 id="林辞-33" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-33" aria-label="Permalink to “林辞”">​</a></h3><p>驕胡犬形，造惡作凶。無所能成，還自滅身。</p><h3 id="注-33" tabindex="-1">注 <a class="header-anchor" href="#注-33" aria-label="Permalink to “注”">​</a></h3><p>詳《明夷》之《大壯》。○犬，汲古訛大，依宋元本。</p><h3 id="解之晉" tabindex="-1">解之晉 <a class="header-anchor" href="#解之晉" aria-label="Permalink to “解之晉”">​</a></h3><h3 id="林辞-34" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-34" aria-label="Permalink to “林辞”">​</a></h3><p>異國他土，出良駿馬。去如奔，害不能傷。</p><h3 id="注-34" tabindex="-1">注 <a class="header-anchor" href="#注-34" aria-label="Permalink to “注”">​</a></h3><p>坤為國土、為馬，艮為良，潘岳《閑居賦》&quot;激矢飛&quot;，此雲奔，言馬疾如奔也。又箭名飛，《方言》雲箭之三鐮長尺六者，謂之飛。晉互坎為矢，奔，坎象也。</p><h3 id="解之明夷" tabindex="-1">解之明夷 <a class="header-anchor" href="#解之明夷" aria-label="Permalink to “解之明夷”">​</a></h3><h3 id="林辞-35" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-35" aria-label="Permalink to “林辞”">​</a></h3><p>恪敬競職，心不作慝。君明臣忠，民賴其福。</p><h3 id="注-35" tabindex="-1">注 <a class="header-anchor" href="#注-35" aria-label="Permalink to “注”">​</a></h3><p>坎為心，震為君，坤為臣、為民。</p><h3 id="解之家人" tabindex="-1">解之家人 <a class="header-anchor" href="#解之家人" aria-label="Permalink to “解之家人”">​</a></h3><h3 id="林辞-36" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-36" aria-label="Permalink to “林辞”">​</a></h3><p>三女求夫，伺候山隅。不見覆關，長思憂嘆。</p><h3 id="注-36" tabindex="-1">注 <a class="header-anchor" href="#注-36" aria-label="Permalink to “注”">​</a></h3><p>詳《乾》之《家人》。</p><h3 id="解之睽" tabindex="-1">解之睽 <a class="header-anchor" href="#解之睽" aria-label="Permalink to “解之睽”">​</a></h3><h3 id="林辞-37" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-37" aria-label="Permalink to “林辞”">​</a></h3><p>駕福乘喜，東至嘉國。戴慶南行，離我室居。</p><h3 id="注-37" tabindex="-1">注 <a class="header-anchor" href="#注-37" aria-label="Permalink to “注”">​</a></h3><p>詳《小畜》之《賁》。</p><h3 id="解之蹇" tabindex="-1">解之蹇 <a class="header-anchor" href="#解之蹇" aria-label="Permalink to “解之蹇”">​</a></h3><h3 id="林辞-38" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-38" aria-label="Permalink to “林辞”">​</a></h3><p>四姦為殘，齊魯道難。前驅執殳，戒守為患。</p><h3 id="注-38" tabindex="-1">注 <a class="header-anchor" href="#注-38" aria-label="Permalink to “注”">​</a></h3><p>《左傳僖二十四年》：&quot;富辰曰聾昧頑囂，狄皆有之，四姦具矣&quot;，坎為姦，伏兌數四，故曰四姦。伏兌為魯，覆巽為齊，艮為殳、為守，坎為患。○殳，汲古訛役，從宋元本。</p><h3 id="解之解" tabindex="-1">解之解 <a class="header-anchor" href="#解之解" aria-label="Permalink to “解之解”">​</a></h3><h3 id="林辞-39" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-39" aria-label="Permalink to “林辞”">​</a></h3><p>駕言出游，鳥鬬車前。更相捽滅，兵寇旦來。回車亟還，可以無憂。</p><h3 id="注-39" tabindex="-1">注 <a class="header-anchor" href="#注-39" aria-label="Permalink to “注”">​</a></h3><p>震為駕、為言、為游、為車，離為鳥，艮為鬬，離正反艮相對，故曰鬬、曰捽。坎隱伏故曰滅。坎為寇，震為旦，故曰兵寇旦來。震為反，故回車亟還。坎憂震解，故無憂。○寇旦，汲古作馬旦，依宋元本。</p><h3 id="解之損" tabindex="-1">解之損 <a class="header-anchor" href="#解之損" aria-label="Permalink to “解之損”">​</a></h3><h3 id="林辞-40" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-40" aria-label="Permalink to “林辞”">​</a></h3><p>下擾上煩，蠧政為患，歲飢無年。</p><h3 id="注-40" tabindex="-1">注 <a class="header-anchor" href="#注-40" aria-label="Permalink to “注”">​</a></h3><p>下互震為擾，上互坤為亂，故曰擾煩。坤為政，伏巽為蟲，故曰蠧政。坤為患、為年歲，坤虛故曰飢。○擾，汲古作憂，依宋元本。政，宋元本作蠱，依汲古。</p><h3 id="解之益" tabindex="-1">解之益 <a class="header-anchor" href="#解之益" aria-label="Permalink to “解之益”">​</a></h3><h3 id="林辞-41" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-41" aria-label="Permalink to “林辞”">​</a></h3><p>雞雉失雛，常畏狐狸。黃池要盟，越國以昌。</p><h3 id="注-41" tabindex="-1">注 <a class="header-anchor" href="#注-41" aria-label="Permalink to “注”">​</a></h3><p>巽為雞，坤文為雉，艮少故曰雛，坤死故失雛。坤為畏，艮為狐狸，狐狸食雛，故畏之。坤為黃，坤水故曰黃池，正反震故曰要盟。坤為國，巽位東南，故曰越國。</p><h3 id="解之夬" tabindex="-1">解之夬 <a class="header-anchor" href="#解之夬" aria-label="Permalink to “解之夬”">​</a></h3><h3 id="林辞-42" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-42" aria-label="Permalink to “林辞”">​</a></h3><p>堅冰黃鳥，終日悲號。不見白粒，但觀蓬蒿。數驚鷙鳥，為我心憂。</p><h3 id="注-42" tabindex="-1">注 <a class="header-anchor" href="#注-42" aria-label="Permalink to “注”">​</a></h3><p>乾為堅冰，伏坤為黃，艮為鳥、為終日，兌口為號，坤憂，故曰悲號。巽為白、為粒，巽覆故不見白粒。坤為茅茹，故曰蓬蒿。伏艮為鷙鳥，坤為心、為憂。○第二句汲古作常哀悲愁，白作米，均依宋元本。第六句宋元本作孰為我憂，依汲古。</p><h3 id="解之姤" tabindex="-1">解之姤 <a class="header-anchor" href="#解之姤" aria-label="Permalink to “解之姤”">​</a></h3><h3 id="林辞-43" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-43" aria-label="Permalink to “林辞”">​</a></h3><p>玉銑鐵頤，倉庫空虛。市賈無盈，與我為仇。</p><h3 id="注-43" tabindex="-1">注 <a class="header-anchor" href="#注-43" aria-label="Permalink to “注”">​</a></h3><p>詳《晉》之《鼎》。○玉銑，元本作玉統，汲古作五銳，依宋本。無，汲古作為，依宋元本。</p><h3 id="解之萃" tabindex="-1">解之萃 <a class="header-anchor" href="#解之萃" aria-label="Permalink to “解之萃”">​</a></h3><h3 id="林辞-44" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-44" aria-label="Permalink to “林辞”">​</a></h3><p>竊名盜位，居非其家。霜隕不實，為陰所賊。</p><h3 id="注-44" tabindex="-1">注 <a class="header-anchor" href="#注-44" aria-label="Permalink to “注”">​</a></h3><p>艮為名位，巽伏故曰盜名竊位。艮為居、為家，盜位故非其家。坤為霜，艮為果蓏，霜殺物故不實。巽為賊。○元本多三句，汲古多一句，皆衍文，依宋本刪。</p><h3 id="解之升" tabindex="-1">解之升 <a class="header-anchor" href="#解之升" aria-label="Permalink to “解之升”">​</a></h3><h3 id="林辞-45" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-45" aria-label="Permalink to “林辞”">​</a></h3><p>賊仁傷德，天怒不福。斬刈宗社，失其本域。</p><h3 id="注-45" tabindex="-1">注 <a class="header-anchor" href="#注-45" aria-label="Permalink to “注”">​</a></h3><p>巽為賊，震為仁德、為怒，伏乾故曰天怒，坤殺故曰斬刈。震為宗，坤為社、為失。○宗，汲古作家，依宋元本。</p><h3 id="解之困" tabindex="-1">解之困 <a class="header-anchor" href="#解之困" aria-label="Permalink to “解之困”">​</a></h3><h3 id="林辞-46" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-46" aria-label="Permalink to “林辞”">​</a></h3><p>萬物初生，蟄蟲振起。益壽增福，日受其喜。</p><h3 id="注-46" tabindex="-1">注 <a class="header-anchor" href="#注-46" aria-label="Permalink to “注”">​</a></h3><p>巽為草莽，故曰萬物，伏震為春，故曰初生。巽為蟲，坎蟄震起，震福，伏艮為壽、為日。○初生，汲古作和生，壽作爵，均依宋元本。</p><h3 id="解之革" tabindex="-1">解之革 <a class="header-anchor" href="#解之革" aria-label="Permalink to “解之革”">​</a></h3><h3 id="林辞-47" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-47" aria-label="Permalink to “林辞”">​</a></h3><p>龍游鳳舞，歲樂民喜。</p><h3 id="注-47" tabindex="-1">注 <a class="header-anchor" href="#注-47" aria-label="Permalink to “注”">​</a></h3><p>伏震為龍，坤為鳳、為歲、為民，震為喜樂。</p><h3 id="解之鼎" tabindex="-1">解之鼎 <a class="header-anchor" href="#解之鼎" aria-label="Permalink to “解之鼎”">​</a></h3><h3 id="林辞-48" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-48" aria-label="Permalink to “林辞”">​</a></h3><p>行行窘步，次宿方舍。居安不懼，姬薑何憂。</p><h3 id="注-48" tabindex="-1">注 <a class="header-anchor" href="#注-48" aria-label="Permalink to “注”">​</a></h3><p>通《屯》。正反震故曰行行，艮止坎陷，故曰窘步。坎為宿，艮為舍，坤方故曰方舍。艮為安居，震為姬，巽為薑，坎憂震解故不憂。○宿，汲古作伯，薑作妾，皆形訛字，依宋元本。</p><h3 id="解之震" tabindex="-1">解之震 <a class="header-anchor" href="#解之震" aria-label="Permalink to “解之震”">​</a></h3><h3 id="林辞-49" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-49" aria-label="Permalink to “林辞”">​</a></h3><p>水深難游，霜寒難涉。商伯失利，旅人稽留。</p><h3 id="注-49" tabindex="-1">注 <a class="header-anchor" href="#注-49" aria-label="Permalink to “注”">​</a></h3><p>互坎水，坤亦為水，四上下重陰，故曰水深。震為游、為涉，坎為霜、為寒，震為伯、為商旅，巽伏，故失利。坎陷艮止，故稽留。</p><h3 id="解之艮" tabindex="-1">解之艮 <a class="header-anchor" href="#解之艮" aria-label="Permalink to “解之艮”">​</a></h3><h3 id="林辞-50" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-50" aria-label="Permalink to “林辞”">​</a></h3><p>跛倚相隨，日暮牛罷。陵遲後旅，失利亡雌。</p><h3 id="注-50" tabindex="-1">注 <a class="header-anchor" href="#注-50" aria-label="Permalink to “注”">​</a></h3><p>詳《大有》之《歸妹》。</p><h3 id="解之漸" tabindex="-1">解之漸 <a class="header-anchor" href="#解之漸" aria-label="Permalink to “解之漸”">​</a></h3><h3 id="林辞-51" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-51" aria-label="Permalink to “林辞”">​</a></h3><p>一牛九鎖，更相牽攣。案明如市，不得東西。請讞得報，日中被刑。</p><h3 id="注-51" tabindex="-1">注 <a class="header-anchor" href="#注-51" aria-label="Permalink to “注”">​</a></h3><p>艮為牛，坎數一，故曰一牛。坎為桎梏，離數九，故曰九鎖。巽為市，離為明，位東，坎位西，艮止，故不得東西。艮為請，坎為刑、為中，艮又為首，否乾首自上落下，中互離，故曰日中被刑。虞翻刻關公首至得隨義同。案：明者，言案驗明白，赴市被刑。</p><h3 id="解之歸妹" tabindex="-1">解之歸妹 <a class="header-anchor" href="#解之歸妹" aria-label="Permalink to “解之歸妹”">​</a></h3><h3 id="林辞-52" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-52" aria-label="Permalink to “林辞”">​</a></h3><p>春桃生花，季女宜家。受福孔多，男為邦君。</p><h3 id="注-52" tabindex="-1">注 <a class="header-anchor" href="#注-52" aria-label="Permalink to “注”">​</a></h3><p>詳《師》之《坤》。震為春、為桃花，兌季。</p><h3 id="解之豐" tabindex="-1">解之豐 <a class="header-anchor" href="#解之豐" aria-label="Permalink to “解之豐”">​</a></h3><h3 id="林辞-53" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-53" aria-label="Permalink to “林辞”">​</a></h3><p>雷鼓東行，稼穡凋傷。大夫執政，君贊其明。</p><h3 id="注-53" tabindex="-1">注 <a class="header-anchor" href="#注-53" aria-label="Permalink to “注”">​</a></h3><p>首句震象，巽為稼穡、為隕落，故凋傷。震為夫、為君，離為明。</p><h3 id="解之旅" tabindex="-1">解之旅 <a class="header-anchor" href="#解之旅" aria-label="Permalink to “解之旅”">​</a></h3><h3 id="林辞-54" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-54" aria-label="Permalink to “林辞”">​</a></h3><p>發輗溫湯，過角宿房。宣時布和，無所不通。</p><h3 id="注-54" tabindex="-1">注 <a class="header-anchor" href="#注-54" aria-label="Permalink to “注”">​</a></h3><p>湯，汲古作陽，角作雨，均依宋元本。○伏震為車，故曰發輗。互坎為水，艮火在下故曰溫湯。艮為星，故曰角房，而角房皆巽方宿，故曰過角宿房。巽四月卦，正角房二宿當值之時，故曰宣時布和。</p><h3 id="解之兌" tabindex="-1">解之兌 <a class="header-anchor" href="#解之兌" aria-label="Permalink to “解之兌”">​</a></h3><h3 id="林辞-55" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-55" aria-label="Permalink to “林辞”">​</a></h3><p>水中大賈，求利食子。商人不至，市空無有。</p><h3 id="注-55" tabindex="-1">注 <a class="header-anchor" href="#注-55" aria-label="Permalink to “注”">​</a></h3><p>互巽為賈、為利，兌為水，故曰水中大賈。震為子，兌為食，伏艮為求，故曰求利食子，言食其資息也。震為商人，震伏故雲不至。巽為市，離中虛，故曰市空。○食子，汲古作十千，依宋元本。三四句宋元本去不字，有上加所字，茲依汲古。</p><h3 id="解之渙" tabindex="-1">解之渙 <a class="header-anchor" href="#解之渙" aria-label="Permalink to “解之渙”">​</a></h3><h3 id="林辞-56" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-56" aria-label="Permalink to “林辞”">​</a></h3><p>春草萌生，萬物敷榮。陰陽和調，國樂無憂。</p><h3 id="注-56" tabindex="-1">注 <a class="header-anchor" href="#注-56" aria-label="Permalink to “注”">​</a></h3><p>巽草震春，震為萌芽，艮國。○調，汲古作暢，依宋元本。</p><h3 id="解之節" tabindex="-1">解之節 <a class="header-anchor" href="#解之節" aria-label="Permalink to “解之節”">​</a></h3><h3 id="林辞-57" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-57" aria-label="Permalink to “林辞”">​</a></h3><p>左眇右盲，目視不明。下民多孽，君失其常。</p><h3 id="注-57" tabindex="-1">注 <a class="header-anchor" href="#注-57" aria-label="Permalink to “注”">​</a></h3><p>震為左，二五互大離，故曰盲，言目無睛也。兌半離，故曰眇。眇，小目也。兌右，故曰左眇右盲。眇象本履卦也。坎為民，兌澤故曰下民。坎為孽，震為君。</p><h3 id="解之中孚" tabindex="-1">解之中孚 <a class="header-anchor" href="#解之中孚" aria-label="Permalink to “解之中孚”">​</a></h3><h3 id="林辞-58" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-58" aria-label="Permalink to “林辞”">​</a></h3><p>悅以內安，不利出門。憂除禍消，公孫何尤。</p><h3 id="注-58" tabindex="-1">注 <a class="header-anchor" href="#注-58" aria-label="Permalink to “注”">​</a></h3><p>兌為悅，在內卦故曰內安，艮為安也。艮門震出，巽隕，故不利。震為公，艮為孫，震解，故憂禍消除。○第三句汲古作憂禍消除。</p><h3 id="解之小過" tabindex="-1">解之小過 <a class="header-anchor" href="#解之小過" aria-label="Permalink to “解之小過”">​</a></h3><h3 id="林辞-59" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-59" aria-label="Permalink to “林辞”">​</a></h3><p>丹書之信，言不負語。易我騏驎，君子有德。</p><h3 id="注-59" tabindex="-1">注 <a class="header-anchor" href="#注-59" aria-label="Permalink to “注”">​</a></h3><p>艮為言，震為言語，正反震相同，故曰不負。震為馬，故曰騏驎，下艮為反震，故曰易。艮為君子。《左傳》裴豹隸也，著於丹書，註：以丹書其罪；又《大戴禮》：&quot;武王問黃帝顓頊之道可得聞乎，尚父曰：在丹書。&quot;此丹書似用左傳。</p><h3 id="解之既濟" tabindex="-1">解之既濟 <a class="header-anchor" href="#解之既濟" aria-label="Permalink to “解之既濟”">​</a></h3><h3 id="林辞-60" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-60" aria-label="Permalink to “林辞”">​</a></h3><p>上政騷擾，螟蟲並起。害我嘉谷，年歲無稷。</p><h3 id="注-60" tabindex="-1">注 <a class="header-anchor" href="#注-60" aria-label="Permalink to “注”">​</a></h3><p>半象，重巽故曰螟蟲並起。餘亦用半象。○螟蟲，汲古作蟲螟，依宋元本。</p><h3 id="解之未濟" tabindex="-1">解之未濟 <a class="header-anchor" href="#解之未濟" aria-label="Permalink to “解之未濟”">​</a></h3><h3 id="林辞-61" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-61" aria-label="Permalink to “林辞”">​</a></h3><p>乾旄旌旗，執職在郊。雖有寶玉，無路致之。</p><h3 id="注-61" tabindex="-1">注 <a class="header-anchor" href="#注-61" aria-label="Permalink to “注”">​</a></h3><p>詳《師》之《隨》。此用半象，職在，汲古作在載，依宋元本。玉，宋元本作珠，依汲古。</p>',312)])])}const f=e(l,[["render",n]]);export{p as __pageData,f as default};
